# Variables secretas de la API, Horizon, migrate y scheduler: VARIABLE=nombre-en-Secret-Manager.
# Equivale al Secret deployer-api-secrets de Kubernetes. Aquí no hay ningún valor: solo el nombre
# del secreto, del que Cloud Run lee la versión `latest` al arrancar cada instancia. secrets.sh los
# crea copiándolos del clúster. deploy.sh omite (con aviso) los que aún no existan.

APP_KEY=deployer-api-app-key
DB_PASSWORD=deployer-api-db-password
REDIS_PASSWORD=deployer-redis-password
REVERB_APP_ID=deployer-reverb-app-id
REVERB_APP_KEY=deployer-reverb-app-key
REVERB_APP_SECRET=deployer-reverb-app-secret
PASSPORT_PRIVATE_KEY=deployer-passport-private-key
PASSPORT_PUBLIC_KEY=deployer-passport-public-key
LOG_SLACK_WEBHOOK_URL=deployer-log-slack-webhook-url
SLACK_WEBHOOK_URL=deployer-slack-webhook-url
MAIL_USERNAME=deployer-mail-username
MAIL_PASSWORD=deployer-mail-password
